{"command": "cat > shellharden.py << 'ENDOFFILE'
#!/usr/bin/env python3
import sys
import re
import argparse
import os

VERSION = "4.3.1"

# ANSI color codes
RESET = "\033[0m"
BOLD = "\033[1m"
UNDERLINE = "\033[4m"
COLORS = {
    'comment': "\033[0;38;2;120;144;96m",
    'keyword': "\033[0;38;2;0;127;255m",
    'string': "\033[0;38;2;63;127;207m",
    'builtin': "\033[0;38;2;192;0;128m",
    'variable': "\033[0;42m",
    'variable_end': "\033[0;42m",
    'command': "\033[0;38;2;192;0;128m",
    'command_end': "\033[m",
    'diff_add': "\033[0;42m",
    'diff_add_end': "\033[m",
}

def tokenize_line(line):
    """Tokenize a line into components for analysis."""
    tokens = []
    i = 0
    while i < len(line):
        if line[i].isspace():
            tokens.append(('whitespace', line[i]))
            i += 1
        elif line[i] == '#':
            # Comment
            end = line.find('\n', i)
            if end == -1:
                end = len(line)
            tokens.append(('comment', line[i:end]))
            i = end + 1
        elif line[i] == '\n':
            tokens.append(('newline', line[i]))
