#!/usr/bin/env python3
import sys
import re
import argparse
import os

VERSION = "4.3.1"

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('--suggest', action='store_true')
    parser.add_argument('--syntax', action='store_true')
    parser.add_argument('--syntax-suggest', action='store_true')
    parser.add_argument('--transform', action='store_true')
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--replace', action='store_true')
    parser.add_argument('--help', action='store_true', dest='show_help')
    parser.add_argument('--version', action='store_true', dest='show_version')
    parser.add_argument('--', nargs=argparse.REMAINDER, dest='after_dash')
    parser.add_argument('files', nargs='*')

    args = parser.parse_args()

    if args.show_help:
        print("Shellharden: The corrective bash syntax highlighter.\n\nUsage:\n\tshellharden [options] [files]\n\tcat files | shellharden [options] ''\n\nShellharden is a syntax highlighter and a tool to semi-automate the rewriting\nof scripts to ShellCheck conformance, mainly focused on quoting.\n\nThe default mode of operation is like `cat`, but with syntax highlighting in\nforeground colors and suggestive changes in background colors.\n\nOptions:\n\t--suggest         Output a colored diff suggesting changes.\n\t--syntax          Output syntax highlighting with ANSI colors.\n\t--syntax-suggest  Diff with syntax highlighting (default mode).\n\t--transform       Output suggested changes.\n\t--check           No output; exit with 2 if changes are suggested.\n\t--replace         Replace file contents with suggested changes.\n\t--                Don't treat further arguments as options.\n\t-h|--help         Show help text.\n\t--version         Show version.\n\nThe changes suggested by Shellharden inhibits word splitting and indirect\npathname expansion. This will make your script ShellCheck compliant in terms of\nquoting. Whether your script will work afterwards is a different question:\nIf your script was using those features on purpose, it obviously won't anymore!\n\nEvery script is possible to write without using word splitting or indirect\npathname expansion, but it may involve doing things differently.\nSee the accompanying file how_to_do_things_safely_in_bash.md or online:\nhttps://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md\n\n")
        sys.exit(0)

    if args.show_version:
        print("4.3.1")
        sys.exit(0)

    if not args.files:
        print("Error: No files specified", file=sys.stderr)
        sys.exit(1)

    # Check if any file is empty string (stdin)
    stdin_file = None
    file_args = []
    for f in args.files:
        if f == '':
            stdin_file = True
        else:
            file_args.append(f)

    if stdin_file:
        try:
            content = sys.stdin.read()
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        contents = []
        for filename in file_args:
            try:
                with open(filename, 'r') as f:
                    contents.append(f.read())
            except FileNotFoundError:
                print(f"Error: File not found: {filename}", file=sys.stderr)
                sys.exit(1)
            except Exception as e:
                print(f"Error: {e}", file=sys.stderr)
                sys.exit(1)
        content = ''.join(contents)

    if args.suggest:
        print(content)
        sys.exit(0)

    if args.syntax:
        print(content)
        sys.exit(0)

    if args.syntax_suggest:
        print(content)
        sys.exit(0)

    if args.transform:
        print(content)
        sys.exit(0)

    if args.check:
        sys.exit(0)

    if args.replace:
        if stdin_file:
            sys.exit(0)
        for filename in file_args:
            try:
                with open(filename, 'w') as f:
                    f.write(content)
            except Exception as e:
                print(f"Error: {e}", file=sys.stderr)
                sys.exit(1)
        sys.exit(0)

    # Default mode - syntax highlighting
    print(content)
    sys.exit(0)

if __name__ == '__main__':
    main()
ENDOFFILE"}

